n( 'qqworld-collector-auto-save-attachment-cron-scan-post', array($this, 'do_cron_scan_post') ); } public function init() { } public function get_scan_args($postdata=null) { if (!$postdata) $postdata = $_REQUEST; $args = array(); $post_types = isset($postdata['qqworld-collector-auto-save-attachments-post-types']) ? $postdata['qqworld-collector-auto-save-attachments-post-types'] : 'post'; $args['post_type'] = $post_types; if (isset($postdata['terms']) && !empty($postdata['terms'])) { $terms = $postdata['terms']; $args['tax_query'] = array( 'relation' => 'OR' ); foreach ($terms as $taxonomy => $term_ids) { $args['tax_query'][] = array( 'taxonomy' => $taxonomy, 'terms' => $term_ids, 'field' => 'id' ); } } $id_from = $postdata['id_from']; $id_to = $postdata['id_to']; $id_from = $id_from=='0' ? 1 : $id_from; $id_to = $id_to=='0' ? 1 : $id_to; $post__in = array(); if (!empty($id_from) && is_numeric($id_from) && empty($id_to)) { $post__in[] = $id_from; } elseif (empty($id_from) && !empty($id_to) && is_numeric($id_to)) { $post__in[] = $id_to; } elseif (!empty($id_from) && is_numeric($id_from) && !empty($id_to) && is_numeric($id_to)) { if ($id_from == $id_to) $post__in[] = $id_from; elseif ($id_from < $id_to) for ($s=$id_from; $s<=$id_to; $s++) $post__in[]=$s; elseif($id_from > $id_to) for ($s=$id_from; $s>=$id_to; $s--) $post__in[]=$s; } $args['post__in'] = $post__in; if (isset($postdata['post_date_after']) && $postdata['post_date_after']) { if (!isset($args['date_query'])) $args['date_query'] = array('inclusive' => true); $datedata = explode('-', $postdata['post_date_after']); $args['date_query']['after'] = array( 'year' => $datedata[0], 'month' => $datedata[1], 'day' => $datedata[2] ); } if (isset($postdata['post_date_before']) && $postdata['post_date_before']) { if (!isset($args['date_query'])) $args['date_query'] = array('inclusive' => true); $datedata = explode('-', $postdata['post_date_before']); $args['date_query']['before'] = array( 'year' => $datedata[0], 'month' =