<?php	 endif; endforeach; exit; } public function set_cron_scan_post() { if (!current_user_can($this->options->qc_authorization_who_can_use)) return; $args = $this->get_scan_args($_POST); if (isset($args['tax_query'])) unset($args['tax_query']['relation']); $schedule = $_POST['schedule']; $args['schedule'] = $schedule; $after_schedule = $_POST['after-schedule'] * 60; $timestamp = time() + $after_schedule; $event_args = array($args); if ($schedule) { wp_schedule_event( $timestamp, $schedule, 'qqworld-collector-auto-save-attachment-cron-scan-post', $event_args); $schedules = wp_get_schedules(); $timestamp += $schedules[$schedule]['interval']; } else { wp_schedule_single_event( $timestamp, 'qqworld-collector-auto-save-attachment-cron-scan-post', $event_args ); } $options = array( $timestamp => $args ); $results = array( 'success' => 1, 'html' => $this->get_cron_table_row($options), 'args' => $args ); echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function delete_schedule() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; $args = json_decode(base64_decode($_POST['args']), true); $timestamp = wp_next_scheduled( 'qqworld-collector-auto-save-attachment-cron-scan-post', array($args) ); if ($timestamp) { wp_unschedule_event( $timestamp, 'qqworld-collector-auto-save-attachment-cron-scan-post', array($args) ); $results = array('success' => 1, 'timestamp' => $timestamp, 'msg' => __('Successfully deleted schedule.', $this->text_domain), 'args' => $args); } else { $results = array('success' => 0,'timestamp' => $timestamp, 'msg' => __('Deleted schedule faied.', $this->text_domain), 'args' => $args); } echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function get_cron_table_row($options) { ob_start(); if (!empty($options)) foreach ($options as $timestamp => $args) { ?>
