 } $content = ob_get_contents(); ob_end_clean(); return $content; } public function clear_all_schedule_crons() { if (!current_user_can($this->options->qc_authorization_who_can_use)) return; $cleaned = $this->clear_all_crons( 'qqworld-collector-auto-save-attachment-cron-scan-post' ); if ($cleaned) { $results = array('success' => 1, 'msg' => __('Successfully cleared all Crons.', $this->text_domain)); } else { $results = array('success' => 0, 'msg' => __('No Crons found.', $this->text_domain)); } echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function do_cron_scan_post($args) { set_time_limit($this->options->qc_stress_timeout); do_action( 'qqworld-collector-log', $this->log_id, __('Start the scan posts task. Arguments:', $this->text_domain), print_r($args, true), true ); $posts = get_posts($args); foreach ($posts as $post) { $post_content = $post->post_content; $attachment_args = array( 'post_id' => $post->ID ); $post->post_content = $this->core->save_attachment->save_remote_attachment($post->post_content, $attachment_args); if ($this->core->save_attachment->has_missing_attachments) { do_action( 'qqworld-collector-log', $this->log_id, __('There are missing / undownloadable attachments', $this->text_domain ), sprintf(__('ID: %s, Title: %s', $this->text_domain), $post->ID, $post->post_title), true ); } $this->core->save_attachment->remove_actions(); $wp_error = wp_update_post($post, true); $this->core->save_attachment->add_actions(); } do_action( 'qqworld-collector-log', $this->log_id, __('Finished the scan posts task.', $this->text_domain), '', true ); } } ?>